import{_ as d,a as e,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"MySQL SELECT 方法速查","description":"按查询需求集中查阅筛选、去重、聚合、JOIN、存在性、排序分页和每组最新记录，配统一样例与预期结果。","frontmatter":{"title":"MySQL SELECT 方法速查","description":"按查询需求集中查阅筛选、去重、聚合、JOIN、存在性、排序分页和每组最新记录，配统一样例与预期结果。","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MySQL SELECT 查询","summary":"按查询需求集中查阅筛选、去重、聚合、JOIN、存在性、排序分页和每组最新记录，配统一样例与预期结果。","status":"active","related":[{"title":"MySQL 操作与命令","link":"/middleware/mysql/plus/ecosystem/mysql-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 查询练习：筛选、NULL 与分页","link":"/middleware/mysql/query-exercises","kind":"应用实践","scope":"general","audience":"general"},{"title":"MySQL 查询语法与函数","link":"/middleware/mysql/plus/subjects/mysql-select-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照","link":"/middleware/mysql/plus/subjects/mysql-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照 · 字符集至其他类似的数据库","link":"/middleware/mysql/plus/subjects/mysql-base-part-02","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"MySQL 子查询与 CTE","link":"/middleware/mysql/plus/subjects/subqueries-cte"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"MySQL 子查询与 CTE","link":"/middleware/mysql/plus/subjects/subqueries-cte"}},"headers":[],"relativePath":"middleware/mysql/plus/subjects/select-methods.md","filePath":"middleware/mysql/plus/subjects/select-methods.md"}'),o={name:"middleware/mysql/plus/subjects/select-methods.md"};function s(l,t,i,c,n,E){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mysql-select-方法速查" tabindex="-1">MySQL SELECT 方法速查 <a class="header-anchor" href="#mysql-select-方法速查" aria-label="Permalink to &quot;MySQL SELECT 方法速查&quot;">​</a></h1><p>先确定“每行结果代表什么”，再选择查询方法：查明细用 WHERE，做统计用 GROUP BY，需要保留明细并计算排名用窗口函数。这里以 MySQL 8.4 为准，重点是 SELECT 的写法和结果含义。</p><h2 id="methods" tabindex="-1">按问题找方法 <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;按问题找方法 {#methods}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想查询什么</th><th>主要写法</th><th>直接阅读</th></tr></thead><tbody><tr><td>满足条件、含空值或重复值的数据</td><td>WHERE、IS NULL、DISTINCT</td><td><a href="#filter">筛选与去重</a></td></tr><tr><td>每个客户的订单数、金额、已完成金额</td><td>GROUP BY、HAVING、条件聚合</td><td><a href="#aggregate">分组统计</a></td></tr><tr><td>带用户名称的订单、没有订单的用户</td><td>JOIN、LEFT JOIN、NOT EXISTS</td><td><a href="#join">关联与存在性</a></td></tr><tr><td>高于平均值的数据、分步骤统计</td><td>标量子查询、派生表、WITH</td><td><a href="/middleware/mysql/plus/subjects/subqueries-cte">子查询与 CTE</a></td></tr><tr><td>每个客户最新一笔、每组前 N、累计金额</td><td>ROW_NUMBER、RANK、SUM OVER</td><td><a href="/middleware/mysql/plus/subjects/window-functions">窗口函数</a></td></tr><tr><td>金额最高的前几笔、继续读取下一页</td><td>ORDER BY、LIMIT、游标条件</td><td><a href="#pagination">排序与分页</a></td></tr><tr><td>拼接文本、处理 NULL、按月显示</td><td>COALESCE、CASE、日期与字符串函数</td><td><a href="/middleware/mysql/plus/subjects/mysql-select-base#functions">查询语法与函数</a></td></tr></tbody></table><details class="details custom-block"><summary>统一样例数据与运行前提</summary><p>先在独立练习库执行<a href="/middleware/mysql/plus/subjects/mysql-select-base#query-data">现有查询样例初始化</a>。以下所有查询共用该数据，不需要为每个例子重新建表。</p><p><code>users(id, name, age, email)</code>：</p><table tabindex="0"><thead><tr><th>id</th><th>name</th><th>age</th><th>email</th></tr></thead><tbody><tr><td>1</td><td>Lin</td><td>25</td><td><a href="mailto:lin@example.com" target="_blank" rel="noopener noreferrer">lin@example.com</a></td></tr><tr><td>2</td><td>Chen</td><td>30</td><td>NULL</td></tr><tr><td>3</td><td>Wu</td><td>22</td><td><a href="mailto:wu@example.com" target="_blank" rel="noopener noreferrer">wu@example.com</a></td></tr></tbody></table><p><code>orders(id, customer_id, amount, status, created_at)</code>：</p><table tabindex="0"><thead><tr><th>id</th><th>customer_id</th><th>amount</th><th>status</th><th>created_at</th></tr></thead><tbody><tr><td>101</td><td>1</td><td>800</td><td>completed</td><td>2024-01-01</td></tr><tr><td>102</td><td>1</td><td>500</td><td>pending</td><td>2024-01-02</td></tr><tr><td>103</td><td>2</td><td>200</td><td>completed</td><td>2024-02-01</td></tr></tbody></table><p>下文是这份固定样例的预期结果。本次整理未连接 MySQL 执行 SQL；修改练习数据后结果会变化。示例无 ORDER BY 时，只说明结果内容，不承诺返回顺序。</p></details><h2 id="filter" tabindex="-1">筛选与去重 <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;筛选与去重 {#filter}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>SQL 示例</th><th>预期结果 / 注意事项</th></tr></thead><tbody><tr><td>选择需要的列</td><td><code>SELECT id, name FROM users ORDER BY id;</code></td><td>1/Lin、2/Chen、3/Wu；比 SELECT * 更明确</td></tr><tr><td>数值范围</td><td><code>SELECT id FROM users WHERE age BETWEEN 23 AND 30 ORDER BY id;</code></td><td>1、2；BETWEEN 包含两端</td></tr><tr><td>多条件组合</td><td><code>SELECT id FROM orders WHERE status = &#39;completed&#39; AND amount &gt;= 500;</code></td><td>101；AND/OR 混用时加括号</td></tr><tr><td>指定几个值</td><td><code>SELECT id FROM orders WHERE status IN (&#39;completed&#39;, &#39;pending&#39;) ORDER BY id;</code></td><td>101、102、103</td></tr><tr><td>查缺失值</td><td><code>SELECT id FROM users WHERE email IS NULL;</code></td><td>2；不写 email = NULL</td></tr><tr><td>前缀匹配</td><td><code>SELECT id FROM users WHERE name LIKE &#39;L%&#39;;</code></td><td>1；大小写规则取决于排序规则</td></tr><tr><td>去重客户</td><td><code>SELECT DISTINCT customer_id FROM orders ORDER BY customer_id;</code></td><td>1、2；DISTINCT 对整个 SELECT 列组合去重</td></tr><tr><td>日期区间</td><td><code>SELECT id FROM orders WHERE created_at &gt;= &#39;2024-01-01&#39; AND created_at &lt; &#39;2024-02-01&#39; ORDER BY id;</code></td><td>101、102；半开区间也适用于带时间的字段</td></tr></tbody></table><h2 id="aggregate" tabindex="-1">分组与条件统计 <a class="header-anchor" href="#aggregate" aria-label="Permalink to &quot;分组与条件统计 {#aggregate}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>SQL 示例</th><th>预期结果 / 注意事项</th></tr></thead><tbody><tr><td>总行数与非空数</td><td><code>SELECT COUNT(*) AS total, COUNT(email) AS filled FROM users;</code></td><td>total=3、filled=2</td></tr><tr><td>每个客户订单数</td><td><code>SELECT customer_id, COUNT(*) AS n FROM orders GROUP BY customer_id ORDER BY customer_id;</code></td><td>1/2、2/1</td></tr><tr><td>找到重复客户</td><td><code>SELECT customer_id, COUNT(*) AS n FROM orders GROUP BY customer_id HAVING COUNT(*) &gt; 1;</code></td><td>1/2；可用于检查重复值，不代表订单重复</td></tr><tr><td>找累计消费超过 1000 的客户</td><td><code>SELECT customer_id, SUM(amount) AS total FROM orders GROUP BY customer_id HAVING SUM(amount) &gt; 1000;</code></td><td>1/1300；WHERE 筛行，HAVING 筛分组</td></tr><tr><td>只统计已完成金额</td><td><code>SELECT customer_id, SUM(CASE WHEN status = &#39;completed&#39; THEN amount ELSE 0 END) AS paid FROM orders GROUP BY customer_id ORDER BY customer_id;</code></td><td>1/800、2/200</td></tr><tr><td>按月统计订单</td><td><code>SELECT DATE_FORMAT(created_at, &#39;%Y-%m&#39;) AS month, COUNT(*) AS n FROM orders GROUP BY month ORDER BY month;</code></td><td>2024-01/2、2024-02/1</td></tr></tbody></table><p>只查询分组键或合法聚合表达式，不通过关闭 ONLY_FULL_GROUP_BY 来掩盖不明确的结果。<code>SUM(DISTINCT amount)</code> 去重的是金额，不是订单；同额的不同订单不应该因此少算。</p><h2 id="join" tabindex="-1">多表关联与存在性 <a class="header-anchor" href="#join" aria-label="Permalink to &quot;多表关联与存在性 {#join}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>SQL 示例</th><th>预期结果 / 注意事项</th></tr></thead><tbody><tr><td>订单附带用户姓名</td><td><code>SELECT o.id, u.name FROM orders o JOIN users u ON u.id = o.customer_id ORDER BY o.id;</code></td><td>101/Lin、102/Lin、103/Chen</td></tr><tr><td>所有用户及订单数</td><td><code>SELECT u.id, COUNT(o.id) AS n FROM users u LEFT JOIN orders o ON o.customer_id = u.id GROUP BY u.id ORDER BY u.id;</code></td><td>1/2、2/1、3/0；COUNT(*) 会把空侧行也计入</td></tr><tr><td>至少有一笔完成订单</td><td><code>SELECT u.id FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = u.id AND o.status = &#39;completed&#39;) ORDER BY u.id;</code></td><td>1、2；每个用户最多返回一行</td></tr><tr><td>没有任何订单</td><td><code>SELECT u.id FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = u.id);</code></td><td>3；不受 NOT IN 子查询含 NULL 的陷阱影响</td></tr></tbody></table><p>外连接先决定“是否保留未匹配用户”。例如筛右表的已完成订单时，将条件放在 ON 可保留没有完成订单的用户；放在 WHERE 则会过滤外连接补出的 NULL 行。</p><p>多个一对多表直接连接后，行数可能被乘大。统计每个用户的两个明细集合时，通常先分别聚合到用户粒度，再连接汇总结果。不要随手加 DISTINCT 或 SUM(DISTINCT amount) 作为通用修复。</p><h2 id="pagination" tabindex="-1">排序、Top N 与分页 <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;排序、Top N 与分页 {#pagination}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>SQL 示例</th><th>预期结果 / 注意事项</th></tr></thead><tbody><tr><td>全局金额最高两笔</td><td><code>SELECT id, amount FROM orders ORDER BY amount DESC, id ASC LIMIT 2;</code></td><td>101/800、102/500；唯一 ID 用于同分时稳定排序</td></tr><tr><td>每页两条的第二页</td><td><code>SELECT id FROM orders ORDER BY id LIMIT 2 OFFSET 2;</code></td><td>103；大偏移通常需要扫描并丢弃许多行</td></tr><tr><td>从上一页继续读</td><td><code>SELECT id FROM orders WHERE id &gt; 102 ORDER BY id LIMIT 2;</code></td><td>103；102 应来自上一页最后一行</td></tr><tr><td>按时间和 ID 继续读</td><td><code>SELECT id FROM orders WHERE created_at &gt; &#39;2024-01-02&#39; OR (created_at = &#39;2024-01-02&#39; AND id &gt; 102) ORDER BY created_at, id LIMIT 2;</code></td><td>103；条件方向必须与排序方向一致</td></tr></tbody></table><p><code>LIMIT 2</code> 只取全局两行；“每个客户最新两笔”需要<a href="/middleware/mysql/plus/subjects/window-functions#top-n">分组窗口排名</a>。同样，先 MAX(created_at) 再任意取其他列，不能保证取到同一条订单。</p><h2 id="check" tabindex="-1">组合查询的三个检查点 <a class="header-anchor" href="#check" aria-label="Permalink to &quot;组合查询的三个检查点 {#check}&quot;">​</a></h2><ol><li><strong>行粒度</strong>：每行是订单、用户还是用户每月？连接后是否变多？</li><li><strong>边界数据</strong>：没有订单、NULL、并列金额、同一天多笔记录是否符合预期？</li><li><strong>访问路径</strong>：确认结果后再用 <a href="/middleware/mysql/base/intermediate/model#indexes">EXPLAIN 与索引</a> 检查扫描和排序，不给所有 SELECT 套固定复杂度。</li></ol><p>应用传入的条件值使用驱动参数绑定；表名、排序列不能当成普通值参数绑定，应通过允许列表选择。不要直接拼接用户输入。</p><p>继续阅读：<a href="/middleware/mysql/plus/practice/mysql-select">查询练习</a>、<a href="https://dev.mysql.com/doc/refman/8.4/en/select.html" target="_blank" rel="noopener noreferrer">MySQL 8.4 SELECT</a>、<a href="https://dev.mysql.com/doc/refman/8.4/en/join.html" target="_blank" rel="noopener noreferrer">JOIN 语法</a>、<a href="https://dev.mysql.com/doc/refman/8.4/en/group-by-handling.html" target="_blank" rel="noopener noreferrer">GROUP BY</a>。</p>',21)])])}const u=d(o,[["render",s]]);export{h as __pageData,u as default};
